INSERT INTO `ai_call_log` VALUES (29, 1, 'huang', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我生成一段职场沟通话术，场景：请教问题。\n\n具体背景：关于项目结构有疑问\n\n请生成得体、专业的沟通话术，要求：\n1. 语言简洁明了，逻辑清晰\n2. 语气礼貌得体，符合职场规范\n3. 提供1-2个不同风格的版本供选择\n4. 每个版本标注适用场景', NULL, 'pending', NULL, NULL, '2026-07-09 19:10:20');
