INSERT INTO `ai_call_log` VALUES (34, 1, 'huang', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n实习第一天应该注意什么？', '\n好的，实习第一天是一个非常重要且令人兴奋的时刻，它不仅是你融入新环境的开始，也是你给未来上司和同事留下第一印象的关键。为了确保你有一个顺利、积极且富有成效的开端，请注意以下几点：\n\n## 📍 一、出发前的准备（Before You Go）\n\n1.  **确认信息与准备材料:**\n    *   **核对细节:** 确认实习的具体地址、时间、时长、岗位职责（即使在第一天可能不明确）。如果不确定，提前一天联系你的实习对接人（可能是学校老师、公司HR或部门主管）。\n    *   **准备文件:** 检查是否需要带身份证、学生证、推荐信、笔记本电脑、笔、USB存储设备🧱等。如果是学校安排的实习，可能还需要带上实习协议或相关证明文件的复印件。\n    *   **了解公司:** 如果方便，可以在前一天快速浏览公司的官方网站、社交媒体账号或新闻稿，对公司业务、文化、近期动态有一个基本了解。\n    *   **着装得体:** 根据公司文化和岗位性质选择合适的着装。通常建议是**商务休闲或正装**。如果不确定，宁可**稍微正式一点**。干净整洁、专业得体的着装会留下好印象。\n    *   **规划路线:** 提前规划好交通路线，考虑可能的延误，确保你能按时甚至提前到达。\n\n## 📌 二、到达与见面（Arrival & Introduction）\n\n1.  **准时或提前到达:**\n    *   **守时是基本素养。** 尽量提前5-10分钟到达公司前台或指定地点。如果乘坐公共交通工具，最好预留更多时间缓冲。\n2.  **主动签到与沟通:**\n    *   到达后，主动在前台或指定地点签到。\n    *   主动查找并联系你的实习对接人或指定联系人（可能是HR、你的导师/主管、或某个部门的员工）。可以说：\"您好，我是[你的名字]，今天来开始我的实习，麻烦找您一下，或者您方便的话告诉我该去哪个部门报道/找谁。\"\n    *   **准备好自我介绍:** 即使对方认识你，也做一下简单的自我介绍，包括你的姓名、学校、专业、实习时间以及你期待从实习中学习什么。\n3.  **保持积极、谦逊、开放的态度:**\n    *   微笑、眼神交流，展现出你热情、乐于学习和合作的态度。\n    *   不要显得过于紧张或拘谨，但也要保持一定的礼节和专业性。\n    *   对新环境、新同事保持好奇和开放的心态。\n\n## 🗣 三、融入与学习（Integration & Learning）\n\n1.  **确认安排，了解任务:**\n    *   你的对接人会告诉你今天的安排：是先熟悉环境？参加欢迎会？还是开始做一些初步的、简单的任务？\n    *   明确你的工作地点（通常是某个办公区域、工位）。\n    *   不要害怕问问题。如果对当天的任务或流程不清楚，及时向对接人或同事请教。\n2.  **观察与倾听:**\n    *   这是最重要的环节之一。观察公司的工作方式、文化氛围、团队协作模式。注意前辈们是如何工作的（如何与人沟通、处理问题、使用工具等）。\n    *   仔细倾听上司或导师的指示，确保你理解正确。可以用自己的话复述一遍来确认。\n3.  **从小事做起，认真负责:**\n    *   即使任务看起来很简单，也要认真对待。仔细阅读邮件、文档，确保理解无误。\n    *   按时完成分配的任务，如果遇到困难及时沟通。\n4.  **带上笔记本或使用工作软件:**\n    *   记录重要的信息、任务、联系方式、需要后续跟进的事情。这不仅方便当天工作，也是你日后总结和提升的素材。\n\n## 🤝 四、沟通与提问（Communication & Questions）\n\n1.  **主动但适度提问:**\n    *   遇到疑问不要憋着，但要学会**观察和判断**什么问题值得问。优先问那些影响你完成任务或理解工作方向的问题。\n    *   可以问：\"这个任务我需要准备些什么？\" \"这份报告的提交格式/渠道是怎样的？\" \"团队通常是如何协作的？\"\n    *   避免在第一天就问过于宽泛或影响他人正常工作的问题。\n2.  **利用机会介绍自己:**\n    *   除了对接人，可以主动向身边正在工作的同事或部门附近的人简单介绍一下自己和你的实习身份。这有助于你快速融入团队。\n    *   保持友好，但不要过于热情地打扰他人工作。\n\n## 🧰 五、保持职业素养（Professionalism）\n\n1.  **维护设备:** 如果使用公司的电脑、电话或其他设备，要小心使用，不安装与工作无关的软件，不泄露公司信息。\n2.  **遵守规定:** 遵守公司的考勤制度、保密协议、安全规定等。\n3.  **保持整洁:** 注意个人仪表和办公环境的整洁。\n4.  **尊重他人:** 尊重你的上司、同事，即使是小事也要有礼貌。\n\n## 📝 六、总结与展望（Wrap-up & Outlook）\n\n1.  **结束当天工作:**\n    *   通常实习第一天不会有太多工作，但最好了解是否有需要在下班前完成或提交的事项。\n    *   整理好个人物品和使用的设备。\n    *   向你的对接人或当天接待你的同事道别，表示感谢：\"今天非常感谢您的帮助，让我快速了解了情况，明天继续努力！\"\n2.  **反思与准备:**\n    *   简单回顾一下第一天的感受和学到的东西。\n    *   对于第二天的工作，如果有疑问或需要准备的，可以提前思考或与对接人沟通。\n3.  **保持学习心态:** 实习是学习的过程，第一天只是开始。保持积极主动，虚心求教，你会收获远超预期。\n\n**总结来说，实习第一天的核心是：** **准备充分、态度积极、遵守规矩、认真观察、主动沟通、从小事做起。**\n\n祝你有一个愉快且有意义的实习开端！', 'success', NULL, 62879, '2026-07-09 19:37:56');
INSERT INTO `ai_call_log` VALUES (35, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为阶段性目标和具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n预计周期：30天\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n```json\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"环境配置与Hello World\",\n      \"startDay\": 1,\n      \"endDay\": 3,\n      \"tasks\": [\n        {\"taskName\": \"安装JDK和配置环境\", \"taskDesc\": \"下载并安装适合的操作系统版本JDK，并完成环境变量配置（JAVA_HOME, PATH, CLASSPATH）\", \"priority\": 1},\n        {\"taskName\": \"创建第一个Java程序\", \"taskDesc\": \"编写、编译并运行一个简单的Hello World程序，理解.java文件到.class文件的编译过程\", \"priority\": 1},\n        {\"taskName\": \"理解Java开发工具集\", \"taskDesc\": \"熟悉使用javac编译、java运行命令，以及IDE（如IntelliJ IDEA）的初步操作\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"基础语法与流程控制\",\n      \"startDay\": 4,\n      \"endDay\": 10,\n      \"tasks\": [\n        {\"taskName\": \"数据类型与变量\", \"taskDesc\": \"掌握Java的基本数据类型（int, double等）、引用类型、变量声明与赋值\", \"priority\": 1},\n        {\"taskName\": \"运算符与表达式\", \"taskDesc\": \"学习算术运算符、关系运算符、逻辑运算符、位运算符等的使用及优先级\", \"priority\": 2},\n        {\"taskName\": \"选择结构\", \"taskDesc\": \"实现if-else、switch-case结构，完成条件判断练习题\", \"priority\": 2},\n        {\"taskName\": \"循环结构\", \"taskDesc\": \"掌握for、while、do-while循环，完成循环嵌套练习及实际应用案例\", \"priority\": 2},\n        {\"taskName\": \"数组基础\", \"taskDesc\": \"理解数组概念，掌握一维和二维数组的声明、初始化与遍历\", \"priority\": 2},\n        {\"taskName\": \"完成基础练习集\", \"taskDesc\": \"每天完成10道基础语法选择题，每周完成2个控制流小项目（如计算器）\", \"priority\": 3}\n      ]\n    },\n    {\n      \"phaseName\": \"面向对象编程\",\n      \"startDay\": 11,\n      \"endDay\": 20,\n      \"tasks\": [\n        {\"taskName\": \"类与对象\", \"taskDesc\": \"理解类（Class）与对象（Object）的概念，学习构造方法、成员变量与方法的定义\", \"priority\": 1},\n        {\"taskName\": \"封装与访问控制\", \"taskDesc\": \"掌握public、private、protected修饰符的使用，实现简单的封装案例\", \"priority\": 2},\n        {\"taskName\": \"继承与多态\", \"taskDesc\": \"理解类继承关系，实现方法重写，掌握向上、向下转型及isInstanceOf\", \"priority\": 1},\n        {\"taskName\": \"抽象类与接口\", \"taskDesc\": \"区分抽象类与接口，完成一个动物类系的案例实现\", \"priority\": 2},\n        {\"taskName\": \"内部类\", \"taskDesc\": \"学习匿名内部类、静态内部类、成员内部类的基本用法\", \"priority\": 3},\n        {\"taskName\": \"完成面向对象练习集\", \"taskDesc\": \"每周完成一个OOP综合项目（如简易学生成绩系统）\", \"priority\": 3}\n      ]\n    },\n    {\n      \"phaseName\": \"核心扩展与综合应用\",\n      \"startDay\": 21,\n      \"endDay\": 30,\n      \"tasks\": [\n        {\"taskName\": \"集合框架学习\", \"taskDesc\": \"掌握List（ArrayList/LinkedList）、Set（HashSet）、Map（HashMap）的核心类及使用场景\", \"priority\": 1},\n        {\"taskName\": \"异常处理机制\", \"taskDesc\": \"理解try-catch-finally、throw、throws的使用，自定义异常类\", \"priority\": 2},\n        {\"taskName\": \"输入输出流\", \"taskDesc\": \"学习FileReader/FileWriter、BufferedReader/BufferedWriter的使用，完成文件读写练习\", \"priority\": 2},\n        {\"taskName\": \"基础语法复习与深化\", \"taskDesc\": \"使用思维导图梳理前两周知识体系，完成100道混合题型练习\", \"priority\": 3},\n        {\"taskName\": \"综合项目实践\", \"taskDesc\": \"开发一个简易待办事项系统，包含增删改查、数据持久化功能\", \"priority\": 1}\n      ]\n    }\n  ]\n}\n```\n\n**规划说明：**\n1. 按照认知曲线分四个阶段，前两周打基础，中间强化核心概念，后段综合应用\n2. 优先级设计：1为重点掌握（需独立完成），2为进阶应用，3为补充练习\n3. 每周设置复习节点，确保知识体系化\n4. 后期项目实践采用\"理论→代码→扩展\"三阶段开发模式\n5. 建议每日学习时长2小时，前阶段每天1.5小时理论+0.5小时实操\n6. 可根据实际进度调整每日任务量，重点保障核心概念的理解深度', 'success', NULL, 60018, '2026-07-09 19:42:14');
INSERT INTO `ai_call_log` VALUES (36, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"基础语法\",\n      \"startDay\": 1,\n      \"endDay\": 10,\n      \"tasks\": [\n        {\"taskName\": \"安装JDK\", \"taskDesc\": \"下载并安装Java Development Kit (JDK) 在您的系统上，确保环境变量配置正确。\", \"priority\": 1},\n        {\"taskName\": \"学习变量和数据类型\", \"taskDesc\": \"理解并实践Java中的基本数据类型，如int, double, char等，并编写简单示例代码。\", \"priority\": 1},\n        {\"taskName\": \"学习运算符\", \"taskDesc\": \"学习算术运算符、关系运算符和逻辑运算符，并在Java程序中应用。\", \"priority\": 2},\n        {\"taskName\": \"学习基本输入输出\", \"taskDesc\": \"练习从控制台读取输入和输出结果，使用Scanner类或System.out.println方法。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"控制流和数据结构\",\n      \"startDay\": 11,\n      \"endDay\": 20,\n      \"tasks\": [\n        {\"taskName\": \"学习if-else语句\", \"taskDesc\": \"实现决策结构，使用if, else if和else语句编写条件判断程序。\", \"priority\": 2},\n        {\"taskName\": \"学习for循环\", \"taskDesc\": \"使用for循环遍历序列，执行重复任务，例如计算阶乘或打印模式。\", \"priority\": 2},\n        {\"taskName\": \"学习while循环\", \"taskDesc\": \"应用while和do-while循环进行条件迭代，处理不确定次数的任务。\", \"priority\": 3},\n        {\"taskName\": \"学习数组\", \"taskDesc\": \"操作数组来存储和处理数据集合，例如排序或搜索数组元素。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"面向对象编程\",\n      \"startDay\": 21,\n      \"endDay\": 30,\n      \"tasks\": [\n        {\"taskName\": \"学习类和对象\", \"taskDesc\": \"定义Java类，创建对象，使用构造函数，并实现封装特性。\", \"priority\": 1},\n        {\"taskName\": \"学习继承和多态\", \"taskDesc\": \"实现继承关系，演示多态行为，例如使用父类引用指向子类对象。\", \"priority\": 1},\n        {\"taskName\": \"学习异常处理\", \"taskDesc\": \"处理异常情况，使用try-catch块编写鲁棒性更强的Java程序。\", \"priority\": 2},\n        {\"taskName\": \"学习集合框架\", \"taskDesc\": \"使用Java集合框架如ArrayList和HashMap来管理动态数据集合。\", \"priority\": 2}\n      ]\n    }\n  ]\n}', 'success', NULL, 59515, '2026-07-09 19:43:55');
INSERT INTO `ai_call_log` VALUES (37, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为阶段性目标和具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n预计周期：30天\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"Java环境设置和基本语法\",\n      \"startDay\": 1,\n      \"endDay\": 10,\n      \"tasks\": [\n        {\"taskName\": \"安装Java Development Kit (JDK)\", \"taskDesc\": \"下载并安装JDK on your computer, ensuring compatibility with your OS.\", \"priority\": 1},\n        {\"taskName\": \"设置Java环境变量\", \"taskDesc\": \"Configure PATH and CLASSPATH variables for command-line access to Java tools.\", \"priority\": 2},\n        {\"taskName\": \"编写第一个Java程序\", \"taskDesc\": \"Create and run a \'Hello World\' program to verify the Java setup.\", \"priority\": 1},\n        {\"taskName\": \"学习基本数据类型\", \"taskDesc\": \"Understand and practice using int, double, char, boolean, and other primitive data types.\", \"priority\": 2},\n        {\"taskName\": \"掌握控制流语句\", \"taskDesc\": \"Study if-else, for, while loops, and switch statements with examples.\", \"priority\": 2},\n        {\"taskName\": \"练习数组使用\", \"taskDesc\": \"Learn and implement one-dimensional and two-dimensional arrays for data storage.\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"面向对象编程\",\n      \"startDay\": 11,\n      \"endDay\": 20,\n      \"tasks\": [\n        {\"taskName\": \"学习类和对象\", \"taskDesc\": \"Define classes, create objects, and invoke methods to understand encapsulation.\", \"priority\": 1},\n        {\"taskName\": \"理解继承和多态\", \"taskDesc\": \"Study inheritance hierarchy and demonstrate polymorphism with examples.\", \"priority\": 2},\n        {\"taskName\": \"学习接口\", \"taskDesc\": \"Implement interfaces to achieve abstraction in Java programs.\", \"priority\": 2},\n        {\"taskName\": \"练习构造函数和方法重载\", \"taskDesc\": \"Practice constructors and method overloading to enhance class functionality.\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"集合框架和异常处理\",\n      \"startDay\": 21,\n      \"endDay\": 30,\n      \"tasks\": [\n        {\"taskName\": \"使用集合框架\", \"taskDesc\": \"Implement List, Set, and Map interfaces (e.g., ArrayList, HashSet, HashMap) with practical examples.\", \"priority\": 1},\n        {\"taskName\": \"处理异常\", \"taskDesc\": \"Learn try-catch blocks and handle common exceptions like NullPointerException or IOException.\", \"priority\": 2},\n        {\"taskName\": \"学习输入输出操作\", \"taskDesc\": \"Work with file I/O using FileReader, FileWriter, or java.nio classes to read and write files.\", \"priority\": 2},\n        {\"taskName\": \"复习和测试\", \"taskDesc\": \"Review all concepts covered and take practice quizzes or small coding exercises to reinforce learning.\", \"priority\": 1}\n      ]\n    }\n  ]\n}', 'success', NULL, 95324, '2026-07-09 19:44:08');
INSERT INTO `ai_call_log` VALUES (38, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为阶段性目标和具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n预计周期：30天\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n```json\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"环境搭建与基础语法\",\n      \"startDay\": 1,\n      \"endDay\": 5,\n      \"tasks\": [\n        {\"taskName\": \"安装JDK\", \"taskDesc\": \"下载并安装JDK（建议使用JDK 17），配置环境变量JAVA_HOME\", \"priority\": 1},\n        {\"taskName\": \"配置开发环境\", \"taskDesc\": \"安装IDE（如IntelliJ IDEA或Eclipse），熟悉基本界面操作\", \"priority\": 1},\n        {\"taskName\": \"编写第一个程序\", \"taskDesc\": \"创建并运行一个简单的Hello World程序，理解Java程序结构\", \"priority\": 1},\n        {\"taskName\": \"学习基本数据类型\", \"taskDesc\": \"掌握byte, short, int, long, float, double, char, boolean等基础类型\", \"priority\": 2},\n        {\"taskName\": \"变量与运算符\", \"taskDesc\": \"学习变量声明、赋值，算术、关系、逻辑运算符的使用\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"流程控制\",\n      \"startDay\": 6,\n      \"endDay\": 15,\n      \"tasks\": [\n        {\"taskName\": \"条件语句\", \"taskDesc\": \"学习if-else、switch-case语句的使用场景与语法\", \"priority\": 1},\n        {\"taskName\": \"循环结构\", \"taskDesc\": \"掌握for、while、do-while循环，理解break和continue的用法\", \"priority\": 1},\n        {\"taskName\": \"异常处理\", \"taskDesc\": \"了解try-catch-finally结构，学习常见异常类型如NullPointerException\", \"priority\": 2},\n        {\"taskName\": \"方法定义与调用\", \"taskDesc\": \"创建方法，理解参数传递机制（值传递），练习方法重载\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"面向对象编程\",\n      \"startDay\": 16,\n      \"endDay\": 20,\n      \"tasks\": [\n        {\"taskName\": \"类与对象\", \"taskDesc\": \"定义类、构造方法、成员变量与方法，理解封装概念\", \"priority\": 1},\n        {\"taskName\": \"继承与多态\", \"taskDesc\": \"实现类继承，掌握super关键字，理解方法重写与向上转型\", \"priority\": 1},\n        {\"taskName\": \"接口与抽象类\", \"taskDesc\": \"创建接口和抽象类，理解它们的区别与应用场景\", \"priority\": 2},\n        {\"taskName\": \"访问修饰符\", \"taskDesc\": \"学习public、private、protected等修饰符的作用范围\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"高级特性与综合\",\n      \"startDay\": 21,\n      \"endDay\": 30,\n      \"tasks\": [\n        {\"taskName\": \"集合框架\", \"taskDesc\": \"掌握List、Set、Map三大接口的常用实现类及操作方法\", \"priority\": 1},\n        {\"taskName\": \"泛型与枚举\", \"taskDesc\": \"理解泛型机制，创建并使用枚举类型\", \"priority\": 2},\n        {\"taskName\": \"Lambda表达式与Stream API\", \"taskDesc\": \"入门使用Lambda简化代码逻辑，处理集合数据流操作\", \"priority\": 2},\n        {\"taskName\": \"复习与实践\", \"taskDesc\": \"完成一个小Java项目（如简易计算器、待办事项清单），巩固所学知识\", \"priority\": 1}\n      ]\n    }\n  ]\n}\n```\n\n### 说明：\n1. **阶段划分**：  \n   - **阶段1（Day 1-5）**：基础环境配置与语法入门。  \n   - **阶段2（Day 6-15）**：重点学习流程控制与异常处理。  \n   - **阶段3（Day 16-20）**：核心面向对象特性（类、继承、接口）。  \n   - **阶段4（Day 21-30）**：高级特性与综合实践。  \n\n2. **任务优先级**：  \n   - `priority=1`：核心知识点，必须掌握；  \n   - `priority=2`：进阶或可选内容，建议完成但非强制。  \n\n3. **灵活性**：  \n   - 若实际学习速度较快，可提前完成任务并进入下一阶段；  \n   - 若遇到困难，可调整任务优先级或延长阶段周期。  \n\n4. **建议**：  \n   - 每天完成1-2个任务，搭配Code Runner或IDE实时调试；  \n   - 使用GitHub记录每日代码提交，形成长期学习习惯。', 'success', NULL, 53252, '2026-07-09 19:44:32');
INSERT INTO `ai_call_log` VALUES (39, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"基础语法\",\n      \"startDay\": 1,\n      \"endDay\": 7,\n      \"tasks\": [\n        {\"taskName\": \"安装Java JDK\", \"taskDesc\": \"下载并安装Java Development Kit (JDK) 和一个集成开发环境 (IDE)，如Eclipse或IntelliJ IDEA，以设置Java开发环境。\", \"priority\": 2},\n        {\"taskName\": \"学习变量和数据类型\", \"taskDesc\": \"掌握Java中的基本数据类型（如int、double、char、boolean）和变量声明与赋值的语法和使用。\", \"priority\": 1},\n        {\"taskName\": \"基本输入输出\", \"taskDesc\": \"学习使用System.out.println()进行输出和Scanner类进行输入操作，以及相关的异常处理基础。\", \"priority\": 1}\n      ]\n    },\n    {\n      \"phaseName\": \"控制流和循环\",\n      \"startDay\": 8,\n      \"endDay\": 14,\n      \"tasks\": [\n        {\"taskName\": \"学习if-else语句\", \"taskDesc\": \"理解并练习条件语句if、else-if和else的语法和应用场景。\", \"priority\": 2},\n        {\"taskName\": \"学习for循环\", \"taskDesc\": \"掌握for循环的语法，包括初始化、条件和迭代部分，并练习常见用例。\", \"priority\": 2},\n        {\"taskName\": \"学习while循环\", \"taskDesc\": \"学习while循环和do-while循环的语法，并比较它们的使用场景。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"类和对象\",\n      \"startDay\": 15,\n      \"endDay\": 21,\n      \"tasks\": [\n        {\"taskName\": \"学习类声明\", \"taskDesc\": \"理解Java中的类声明语法，包括访问修饰符（public、private、protected）和成员变量的定义。\", \"priority\": 1},\n        {\"taskName\": \"学习构造函数\", \"taskDesc\": \"掌握构造函数的概念、语法和作用，包括无参数和有参数构造函数的使用。\", \"priority\": 1},\n        {\"taskName\": \"学习方法\", \"taskDesc\": \"理解方法的定义、参数传递、返回值和重载概念，并练习方法的调用。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"综合练习\",\n      \"startDay\": 22,\n      \"endDay\": 28,\n      \"tasks\": [\n        {\"taskName\": \"复习所有概念\", \"taskDesc\": \"回顾Java基础语法、控制流、类和对象等所有已学内容，确保理解和记忆。\", \"priority\": 3},\n        {\"taskName\": \"完成一个简单项目\", \"taskDesc\": \"使用所学Java知识编写一个简单项目，如一个计算器应用或待办事项列表，以整合和应用所学技能。\", \"priority\": 3}\n      ]\n    }\n  ]\n}', 'success', NULL, 83841, '2026-07-09 19:45:29');
INSERT INTO `ai_call_log` VALUES (40, 1, '', 3, '智能问答模板', 'answer', '请详细回答以下问题：\n\n请帮我将以下目标拆解为阶段性目标和具体任务：\n\n目标名称：学Java\n目标描述：学习Java基础\n预计周期：30天\n\n请按照以下格式输出JSON：\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"阶段名称\",\n      \"startDay\": 开始天数,\n      \"endDay\": 结束天数,\n      \"tasks\": [\n        {\"taskName\": \"任务名称\", \"taskDesc\": \"任务描述\", \"priority\": 优先级(1-3)}\n      ]\n    }\n  ]\n}', '\n{\n  \"phases\": [\n    {\n      \"phaseName\": \"Java基础语法阶段\",\n      \"startDay\": 1,\n      \"endDay\": 10,\n      \"tasks\": [\n        {\"taskName\": \"安装JDK和配置环境\", \"taskDesc\": \"安装Java Development Kit (JDK) 并设置环境变量，确保可以编译和运行Java程序。\", \"priority\": 1},\n        {\"taskName\": \"编写Hello World程序\", \"taskDesc\": \"创建一个简单的Java程序，输出 \'Hello, World!\'，理解Java程序的基本结构。\", \"priority\": 2},\n        {\"taskName\": \"学习数据类型\", \"taskDesc\": \"学习Java的基本数据类型（如int、double、boolean、char等），包括它们的大小、范围和用法，并编写示例代码。\", \"priority\": 1},\n        {\"taskName\": \"运算符\", \"taskDesc\": \"学习算术、关系和逻辑运算符，使用它们编写表达式和简单计算。\", \"priority\": 2},\n        {\"taskName\": \"if-else语句\", \"taskDesc\": \"学习使用if、else-if、else语句进行条件判断，并编写示例代码处理不同场景。\", \"priority\": 1},\n        {\"taskName\": \"for循环\", \"taskDesc\": \"学习for循环语法，编写计数器和迭代示例，如计算总和或遍历数组。\", \"priority\": 2},\n        {\"taskName\": \"while循环\", \"taskDesc\": \"学习while循环，并与for循环比较使用场景，编写示例代码处理不确定次数的操作。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"面向对象编程阶段\",\n      \"startDay\": 11,\n      \"endDay\": 20,\n      \"tasks\": [\n        {\"taskName\": \"类和对象\", \"taskDesc\": \"学习Java类定义、对象创建，使用关键字class和new，理解封装概念。\", \"priority\": 1},\n        {\"taskName\": \"构造器\", \"taskDesc\": \"理解构造器的概念，编写有参数和无参数构造器，并初始化对象属性。\", \"priority\": 2},\n        {\"taskName\": \"继承\", \"taskDesc\": \"学习类继承，使用extends关键字，理解方法重写和super关键字用法。\", \"priority\": 1},\n        {\"taskName\": \"多态\", \"taskDesc\": \"学习多态的概念，使用父类引用调用子类方法，并编写示例代码演示多态性。\", \"priority\": 2},\n        {\"taskName\": \"接口\", \"taskDesc\": \"学习接口定义和实现，理解抽象类与接口的区别，并编写示例代码。\", \"priority\": 1},\n        {\"taskName\": \"异常处理\", \"taskDesc\": \"学习try-catch-finally结构，处理常见异常如IOException，并理解异常层次结构。\", \"priority\": 2}\n      ]\n    },\n    {\n      \"phaseName\": \"综合和应用阶段\",\n      \"startDay\": 21,\n      \"endDay\": 30,\n      \"tasks\": [\n        {\"taskName\": \"集合框架\", \"taskDesc\": \"学习使用ArrayList或HashMap进行数据存储、检索和操作，并编写示例代码演示基本用法。\", \"priority\": 1},\n        {\"taskName\": \"简单项目开发\", \"taskDesc\": \"开发一个简单的Java应用程序，如命令行计算器或待办事项列表，应用所学知识解决实际问题。\", \"priority\": 1},\n        {\"taskName\": \"复习和自我测试\", \"taskDesc\": \"复习所有学习内容，编写测试代码确认理解，并进行自我评估以识别弱点。\", \"priority\": 3}\n      ]\n    }\n  ]\n}', 'success', NULL, 198073, '2026-07-10 08:44:04');

-- ----------------------------
-- Table structure for ai_prompt_template
-- ----------------------------
DROP TABLE IF EXISTS `ai_prompt_template`;
CREATE TABLE `ai_prompt_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID，主键自增',
  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `template_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板编码（唯一标识）',
  `template_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板内容（支持变量占位符）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模板描述',
  `scene_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场景类型：polish-润色，review-复盘，answer-生成答案，summary-总结，translate-翻译',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用，1-启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `template_code`(`template_code` ASC) USING BTREE,
  INDEX `idx_template_code`(`template_code` ASC) USING BTREE,
  INDEX `idx_scene_type`(`scene_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI提示词模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_prompt_template
-- ----------------------------
INSERT INTO `ai_prompt_template` VALUES (1, '文本润色模板', 'POLISH_TEMPLATE', '请对以下文本进行润色优化，使其更加通顺、专业、优美：\n\n{{content}}', '用于文本润色场景，优化文本表达', 'polish', 1, '2026-07-06 14:50:56', '2026-07-06 14:50:56');
INSERT INTO `ai_prompt_template` VALUES (2, '复盘分析模板', 'REVIEW_TEMPLATE', '请对以下工作记录进行复盘分析，从三个维度总结：\\n\\n{{content}}\\n\\n【亮点】：做得好的地方\\n【不足】：需要改进的地方\\n【建议】：具体改进措施\' ', '用于复盘分析场景，帮助总结经验教训', 'review', 1, '2026-07-06 14:50:56', '2026-07-08 14:55:28');
INSERT INTO `ai_prompt_template` VALUES (3, '智能问答模板', 'ANSWER_TEMPLATE', '请详细回答以下问题：\n\n{{question}}', '用于智能问答场景，生成问题答案', 'answer', 1, '2026-07-06 14:50:56', '2026-07-06 14:50:56');
INSERT INTO `ai_prompt_template` VALUES (4, '文本总结模板', 'SUMMARY_TEMPLATE', '请对以下文本进行总结，提炼核心要点：\n\n{{content}}', '用于文本总结场景，提取关键信息', 'summary', 1, '2026-07-06 14:50:56', '2026-07-06 14:50:56');
INSERT INTO `ai_prompt_template` VALUES (5, '文本翻译模板', 'TRANSLATE_TEMPLATE', '请将以下文本翻译成{{targetLang}}：\n\n{{content}}', '用于文本翻译场景，支持多种语言', 'translate', 1, '2026-07-06 14:50:56', '2026-07-06 14:50:56');
INSERT INTO `ai_prompt_template` VALUES (6, '文本摘要精简', 'text_summary', '请将以下工作日报内容精简为结构化的要点清单，只保留核心工作内容和问题，去掉冗余表述，总字数控制在原文的30%以内，分点输出：\n\n{{content}}', NULL, 'summary', 1, '2026-07-09 09:17:59', '2026-07-09 09:17:59');

-- ----------------------------
-- Table structure for ai_system_config
-- ----------------------------
DROP TABLE IF EXISTS `ai_system_config`;
CREATE TABLE `ai_system_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID，主键自增',
  `config_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键（如AI_API_KEY、AI_BASE_URL、AI_MODEL_NAME）',
  `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '配置值',
  `config_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '配置名称（用于前端显示）',
  `config_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '配置描述',
  `config_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'string' COMMENT '配置类型：string-字符串，password-密码，number-数字，boolean-布尔',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用，1-启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `config_key`(`config_key` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI系统配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ai_system_config
-- ----------------------------
