INSERT INTO `goal_task` VALUES (1, 1, 1, '安装JDK', '下载并安装Java Development Kit (JDK) 在您的系统上，确保环境变量配置正确。', 1, NULL, 0, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (2, 1, 1, '学习变量和数据类型', '理解并实践Java中的基本数据类型，如int, double, char等，并编写简单示例代码。', 1, NULL, 1, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (3, 1, 1, '学习运算符', '学习算术运算符、关系运算符和逻辑运算符，并在Java程序中应用。', 2, NULL, 2, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (4, 1, 1, '学习基本输入输出', '练习从控制台读取输入和输出结果，使用Scanner类或System.out.println方法。', 2, NULL, 3, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (5, 1, 1, '学习if-else语句', '实现决策结构，使用if, else if和else语句编写条件判断程序。', 2, NULL, 4, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (6, 1, 1, '学习for循环', '使用for循环遍历序列，执行重复任务，例如计算阶乘或打印模式。', 2, NULL, 5, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (7, 1, 1, '学习while循环', '应用while和do-while循环进行条件迭代，处理不确定次数的任务。', 3, NULL, 6, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (8, 1, 1, '学习数组', '操作数组来存储和处理数据集合，例如排序或搜索数组元素。', 2, NULL, 7, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (9, 1, 1, '学习类和对象', '定义Java类，创建对象，使用构造函数，并实现封装特性。', 1, NULL, 8, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (10, 1, 1, '学习继承和多态', '实现继承关系，演示多态行为，例如使用父类引用指向子类对象。', 1, NULL, 9, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (11, 1, 1, '学习异常处理', '处理异常情况，使用try-catch块编写鲁棒性更强的Java程序。', 2, NULL, 10, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (12, 1, 1, '学习集合框架', '使用Java集合框架如ArrayList和HashMap来管理动态数据集合。', 2, NULL, 11, 1, '2026-07-09 19:44:55', '2026-07-09 19:44:55');
INSERT INTO `goal_task` VALUES (13, 1, 1, '安装Java JDK', '下载并安装Java Development Kit (JDK) 和一个集成开发环境 (IDE)，如Eclipse或IntelliJ IDEA，以设置Java开发环境。', 2, NULL, 0, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (14, 1, 1, '学习变量和数据类型', '掌握Java中的基本数据类型（如int、double、char、boolean）和变量声明与赋值的语法和使用。', 1, NULL, 1, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (15, 1, 1, '基本输入输出', '学习使用System.out.println()进行输出和Scanner类进行输入操作，以及相关的异常处理基础。', 1, NULL, 2, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (16, 1, 1, '学习if-else语句', '理解并练习条件语句if、else-if和else的语法和应用场景。', 2, NULL, 3, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (17, 1, 1, '学习for循环', '掌握for循环的语法，包括初始化、条件和迭代部分，并练习常见用例。', 2, NULL, 4, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (18, 1, 1, '学习while循环', '学习while循环和do-while循环的语法，并比较它们的使用场景。', 2, NULL, 5, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (19, 1, 1, '学习类声明', '理解Java中的类声明语法，包括访问修饰符（public、private、protected）和成员变量的定义。', 1, NULL, 6, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (20, 1, 1, '学习构造函数', '掌握构造函数的概念、语法和作用，包括无参数和有参数构造函数的使用。', 1, NULL, 7, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (21, 1, 1, '学习方法', '理解方法的定义、参数传递、返回值和重载概念，并练习方法的调用。', 2, NULL, 8, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (22, 1, 1, '复习所有概念', '回顾Java基础语法、控制流、类和对象等所有已学内容，确保理解和记忆。', 3, NULL, 9, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');
INSERT INTO `goal_task` VALUES (23, 1, 1, '完成一个简单项目', '使用所学Java知识编写一个简单项目，如一个计算器应用或待办事项列表，以整合和应用所学技能。', 3, NULL, 10, 1, '2026-07-09 19:46:53', '2026-07-09 19:46:53');

