INSERT INTO `review_record` VALUES (3, 1, 'daily', '2026-07-07', '2026-07-07', '=== 日报日期：2026-07-07 ===\n今日完成：\n完成AI模块开发，对外提供接口\n遇到问题：\nAI有点慢\n明日计划：\n完成日报周报管理功能\n\n', NULL, NULL, NULL, NULL, 0, NULL, '2026-07-08 15:46:17', '2026-07-08 15:46:17');
