-- ----------------------------
-- Table structure for weekly_report
-- ----------------------------
DROP TABLE IF EXISTS `weekly_report`;
CREATE TABLE `weekly_report`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '周报ID，主键自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `week_year` int NOT NULL COMMENT '年份',
  `week_num` int NOT NULL COMMENT '周次（当年第几周）',
  `start_date` date NOT NULL COMMENT '本周开始日期',
  `end_date` date NOT NULL COMMENT '本周结束日期',
  `week_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '本周工作总结',
  `problem_review` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '问题与复盘',
  `next_week_plan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '下周工作计划',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态：0-草稿，1-已提交',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_week`(`week_year` ASC, `week_num` ASC) USING BTREE,
  INDEX `idx_user_week`(`user_id` ASC, `week_year` ASC, `week_num` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '周报表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of weekly_report
-- ----------------------------
INSERT INTO `weekly_report` VALUES (1, 1, 2026, 28, '2026-07-06', '2026-07-12', '【2026-07-07】\r\n完成AI模块开发，对外提供接口\r\n\r\n【2026-07-06】\r\n\r\n\r\n原句“完成项目基本框架搭建”表意清晰，但略显平淡，缺乏力度和质感。为了使其更加通顺、专业且优美，可以根据**使用场景**的不同，参考以下几种优化方案：\r\n\r\n### 1. 通用专业版（适用于周报、项目进度单）\r\n> **“项目基础架构已顺利构建，为后续开发奠定基石。”**\r\n*   **解析：** 将“完成”改为“已顺利构建”，增加了过程感；增加后半句，体现了该动作的价值（“奠定基础”），显得更有条理。\r\n\r\n### 2. 简历/绩效版（适用于求职、年终总结，强调个人贡献）\r\n> **“主导项目整体架构的设计与落地，确立核心开发框架。”**\r\n*   **解析：** 使用“主导”、“设计”、“落地”等强动词，体现主动性和掌控力；“确立核心”比“基本”更具分量，突显技术深度。\r\n\r\n### 3. 正式汇报版（适用于 PPT 演示、正式公文，强调宏观布局）\r\n> **“擘画项目蓝图，夯实基础架构，完成底层逻辑搭建。”**\r\n*   **解析：** 运用“擘画”、“夯实”等词汇，提升了文字的文化底蕴和正式感；“底层逻辑”比“基本框架”更具技术深度和抽象美感。\r\n\r\n### 4. 精炼有力版（适用于标题、摘要，强调结果）\r\n> **“基础架构搭建告捷，项目基石已筑。”**\r\n*   **解析：** 对仗工整，节奏感强。“告捷”与“已筑”富有画面感，简洁而有力。\r\n\r\n### 5. 侧重技术实现版（适用于技术文档、架构评审）\r\n> **“完成系统顶层架构规划，实现模块间的高效解耦与框架部署。”**\r\n*   **解析：** 针对技术场景，将“搭建”具体化为“规划”、“解耦”、“部署”，体现了技术细节的把控。\r\n\r\n---\r\n\r\n### 💡 词汇升级小贴士\r\n如果您想自己微调，可以尝试以下词汇替换，瞬间提升专业度：\r\n*   **完成** $\\rightarrow$ 确立、构建、落地、夯实、落成\r\n*   **项目** $\\rightarrow$ 系统、引擎、平台、底层\r\n*   **基本** $\\rightarrow$ 核心、顶层、底层、宏观\r\n*   **搭建** $\\rightarrow$ 构建、规划、部署、筑基\r\n\r\n**推荐首选：**\r\n如果是日常汇报，建议使用：**“项目基础架构已顺利构建，为后续开发奠定坚实基础。”** 既专业又得体。\r\n\r\n', '【2026-07-07】\r\nAI有点慢\r\n\r\n【2026-07-06】\r\n无\r\n\r\n', '', 1, '2026-07-07 14:21:32', '2026-07-07 14:21:57');

